/**
 * A small Java source builder: collects imports while the body is written, renders the
 * header comment, the package line, sorted imports and the body with four-space indentation
 * and LF line ends. Literal helpers turn JSON values into Java literals.
 *
 * @packageDocumentation
 */

/** One Java source file under construction. */
export class JavaFile {
  private readonly imports = new Set<string>();

  /**
   * @param javaPackage - The file's package.
   * @param source - What the file was generated from, named in the header comment.
   */
  constructor(
    readonly javaPackage: string,
    readonly source: string,
  ) {}

  /**
   * Imports a class and returns its simple name. A nested class is imported through its
   * outer class: `use('net.minecraft.world.level.levelgen.Heightmap', 'Types')` imports
   * `Heightmap` and returns `Heightmap.Types`.
   *
   * @param fqcn - The fully qualified class name (outer class only, for nested ones).
   * @param nested - Nested class names appended to the simple name, for example `Types`.
   */
  use(fqcn: string, ...nested: string[]): string {
    const simple = fqcn.slice(fqcn.lastIndexOf('.') + 1);
    const packageName = fqcn.slice(0, fqcn.lastIndexOf('.'));
    if (packageName !== this.javaPackage && packageName !== 'java.lang') this.imports.add(fqcn);
    return [simple, ...nested].join('.');
  }

  /**
   * Renders the file.
   *
   * @param body - The lines after the imports (the class declaration and its members), at
   *   indentation level 0; nested levels are already indented with four spaces.
   */
  render(body: readonly string[]): string {
    const lines = [`// Generated by MCSuperMods from ${this.source}.`, `package ${this.javaPackage};`, ''];
    const imports = [...this.imports].sort();
    if (imports.length > 0) {
      for (const fqcn of imports) lines.push(`import ${fqcn};`);
      lines.push('');
    }
    lines.push(...body);
    return `${lines.map((line) => line.replace(/\s+$/, '')).join('\n')}\n`;
  }
}

/** Indents every non-empty line by `levels` times four spaces. */
export function indent(lines: readonly string[], levels = 1): string[] {
  const pad = '    '.repeat(levels);
  return lines.map((line) => (line === '' ? '' : `${pad}${line}`));
}

/** A Java string literal. */
export function javaString(value: string): string {
  let out = '"';
  for (const char of value) {
    const code = char.codePointAt(0) as number;
    if (char === '"') out += '\\"';
    else if (char === '\\') out += '\\\\';
    else if (char === '\n') out += '\\n';
    else if (char === '\r') out += '\\r';
    else if (char === '\t') out += '\\t';
    else if (code < 0x20 || (code >= 0x7f && code < 0xa0)) {
      out += `\\u${code.toString(16).padStart(4, '0')}`;
    } else out += char;
  }
  return `${out}"`;
}

/** A Java `float` literal: `3` is `3.0f`, `0.4` is `0.4f`, `1e-7` is `1e-7f`. */
export function javaFloat(value: number): string {
  if (!Number.isFinite(value)) throw new Error(`${value} is not a finite number`);
  const text = String(value);
  return /[.e]/.test(text) ? `${text}f` : `${text}.0f`;
}

/** A Java `int` literal; throws when the value is not a 32-bit integer. */
export function javaInt(value: number): string {
  if (!Number.isInteger(value) || value < -2147483648 || value > 2147483647) {
    throw new Error(`${value} is not an int`);
  }
  return String(value);
}

/** `Identifier.fromNamespaceAndPath("<ns>", "<path>")` for a resource location. */
export function identifierExpression(file: JavaFile, id: string): string {
  const colon = id.indexOf(':');
  const namespace = colon < 0 ? 'minecraft' : id.slice(0, colon);
  const path = colon < 0 ? id : id.slice(colon + 1);
  const identifier = file.use('net.minecraft.resources.Identifier');
  return `${identifier}.fromNamespaceAndPath(${javaString(namespace)}, ${javaString(path)})`;
}

/** The lines without leading and trailing empty lines. */
export function trimBlank(lines: readonly string[]): string[] {
  let start = 0;
  let end = lines.length;
  while (start < end && lines[start] === '') start++;
  while (end > start && lines[end - 1] === '') end--;
  return lines.slice(start, end);
}
